1	import { CONTACT_WIZARD } from "../config/component.config.js";
2	import {
3	  CONTACT_THEATRE_SUCCESS_DEFAULT_MESSAGE,
4	  CONTACT_THEATRE_SUCCESS_FLOW_REQUEST_EVENT,
5	} from "../pages/contact/theatre/ContactTheatreConfig.js";
6	import { BlockReveal } from "../animation/BlockReveal.js";
7	import { BLOCK_HIDDEN_CLASS, INIT_DOM_CLASSES } from "../config/dom.config.js";
8	import { Debounce } from "../utils/Debounce.js";
9	import type {
10	  ContactWizardChipData,
11	  ContactWizardInitOptions,
12	} from "../types/component.types.js";
13	import type {
14	  ContactSubmitResponse,
15	  ContactSuccessFlowRequestDetail,
16	} from "../types/contact.types.js";
17	
18	export class ContactWizard {
19	  private static readonly _CLASS = "ContactWizard";
20	  private readonly _root: HTMLElement;
21	  private readonly _form: HTMLFormElement | null;
22	  private readonly _viewport: HTMLElement | null;
23	  private readonly _steps: HTMLElement[];
24	  private readonly _overviewList: HTMLOListElement | null;
25	  private readonly _prevButtons: HTMLButtonElement[];
26	  private readonly _primaryActionButtons: HTMLButtonElement[];
27	  private readonly _projectOtherToggle: HTMLInputElement | null;
28	  private readonly _projectOtherPanel: HTMLElement | null;
29	  private readonly _projectOtherInput: HTMLInputElement | null;
30	  private readonly _sidebarSyncDebounce: Debounce;
31	  private readonly _chipLeaveTimers = new WeakMap<HTMLElement, number>();
32	  private readonly _chipMoveAnimations = new WeakMap<HTMLElement, Animation>();
33	  private readonly _previousActionHideTimers = new WeakMap<HTMLElement, number>();
34	  private readonly _activeTimers = new Set<number>();
35	  private readonly _activeAnimations = new Set<Animation>();
36	  private readonly _onClickBound: (event: Event) => void;
37	  private readonly _onChangeBound: () => void;
38	  private readonly _onInputBound: (event: Event) => void;
39	  private readonly _onSubmitBound: (event: Event) => void;
40	  private readonly _onFormKeydownBound: (event: KeyboardEvent) => void;
41	  private _mounted = false;
42	  private _disposed = false;
43	  private _navItems: HTMLElement[] = [];
44	  private _stepValues: HTMLElement[] = [];
45	  private _current = 0;
46	  private _busy = false;
47	  private _submitting = false;
48	  private _lastOverviewScrollIndex = -1;
49	
50	  private static _instances = new Set<ContactWizard>();
51	
52	  static init(options: ContactWizardInitOptions = {}): void {
53	    const scope = options.root ?? document;
54	    scope
55	      .querySelectorAll<HTMLElement>(CONTACT_WIZARD.selector)
56	      .forEach((element) => {
57	        const instance = new ContactWizard(element);
58	        ContactWizard._instances.add(instance);
59	        instance.mount();
60	      });
61	  }
62	
63	  static dispose(): void {
64	    ContactWizard._instances.forEach((instance) => instance.dispose());
65	    ContactWizard._instances.clear();
66	  }
67	
68	  constructor(root: HTMLElement) {
69	    this._root = root;
70	    this._form = root.closest("form");
71	    this._viewport = root.querySelector<HTMLElement>("[data-wizard-viewport]");
72	    this._steps = Array.from(
73	      root.querySelectorAll<HTMLElement>("[data-wizard-step]"),
74	    );
75	    this._overviewList = root.querySelector<HTMLOListElement>(
76	      "[data-wizard-overview-list]",
77	    );
78	    this._prevButtons = Array.from(
79	      root.querySelectorAll<HTMLButtonElement>("[data-wizard-prev]"),
80	    );
81	    this._primaryActionButtons = Array.from(
82	      root.querySelectorAll<HTMLButtonElement>("[data-wizard-primary-action]"),
83	    );
84	    this._projectOtherToggle = root.querySelector<HTMLInputElement>(
85	      "[data-project-other-toggle]",
86	    );
87	    this._projectOtherPanel = root.querySelector<HTMLElement>(
88	      "[data-project-other-panel]",
89	    );
90	    this._projectOtherInput = root.querySelector<HTMLInputElement>(
91	      "[data-project-other-input]",
92	    );
93	    this._sidebarSyncDebounce = new Debounce(
94	      CONTACT_WIZARD.summaryInputDebounceMs,
95	    );
96	    this._onClickBound = (event) => this._onClick(event as MouseEvent);
97	    this._onChangeBound = () => {
98	      this._sidebarSyncDebounce.offCancel();
99	      this._syncProjectOtherField();
100	      this._syncSidebar();
101	    };
102	    this._onInputBound = (event) => {
103	      this._syncProjectOtherField();
104	      if (this._shouldDebounceSidebarSync(event.target)) {
105	        this._sidebarSyncDebounce.runDebounce(() => this._syncSidebar());
106	        return;
107	      }
108	      this._syncSidebar();
109	    };
110	    this._onSubmitBound = (event) => this._onSubmit(event as SubmitEvent);
111	    this._onFormKeydownBound = (event) => this._onFormKeydown(event);
112	  }
113	
114	  dispose(): void {
115	    if (this._disposed) return;
116	    this._disposed = true;
117	    if (this._mounted) {
118	      this._root.removeEventListener("click", this._onClickBound);
119	      this._root.removeEventListener("change", this._onChangeBound);
120	      this._root.removeEventListener("input", this._onInputBound);
121	      this._form?.removeEventListener("submit", this._onSubmitBound);
122	      this._form?.removeEventListener("keydown", this._onFormKeydownBound, true);
123	      this._mounted = false;
124	    }
125	    this._sidebarSyncDebounce.offCancel();
126	    this._activeTimers.forEach((id) => window.clearTimeout(id));
127	    this._activeTimers.clear();
128	    this._activeAnimations.forEach((animation) => animation.cancel());
129	    this._activeAnimations.clear();
130	    ContactWizard._instances.delete(this);
131	  }
132	
133	  private _trackedTimeout(callback: () => void, delay: number): number {
134	    const id = window.setTimeout(() => {
135	      this._activeTimers.delete(id);
136	      if (this._disposed) return;
137	      callback();
138	    }, delay);
139	    this._activeTimers.add(id);
140	    return id;
141	  }
142	
143	  private _trackAnimation(animation: Animation): Animation {
144	    this._activeAnimations.add(animation);
145	    const cleanup = () => this._activeAnimations.delete(animation);
146	    animation.addEventListener("finish", cleanup, { once: true });
147	    animation.addEventListener("cancel", cleanup, { once: true });
148	    return animation;
149	  }
150	
151	  private mount(): void {
152	    if (!this._viewport || this._steps.length === 0) return;
153	
154	    const totalElement =
155	      this._root.querySelector<HTMLElement>("[data-wizard-total]");
156	    if (totalElement) {
157	      totalElement.textContent = String(this._steps.length).padStart(2, "0");
158	    }
159	
160	    this._renderOverview();
161	    this._root.addEventListener("click", this._onClickBound);
162	    this._root.addEventListener("change", this._onChangeBound);
163	    this._root.addEventListener("input", this._onInputBound);
164	    this._form?.addEventListener("submit", this._onSubmitBound);
165	    this._form?.addEventListener("keydown", this._onFormKeydownBound, true);
166	    this._mounted = true;
167	
168	    this._steps.forEach((step, index) => {
169	      step.classList.toggle("is-active", index === 0);
170	      step.classList.remove("is-prev");
171	    });
172	
173	    this._syncIndicator(true);
174	    this._syncProjectOtherField();
175	    this._syncSidebar();
176	  }
177	
178	  private _renderOverview(): void {
179	    if (!this._overviewList) return;
180	
181	    const fragment = document.createDocumentFragment();
182	    this._steps.forEach((step, index) => {
183	      const item = document.createElement("li");
184	      item.className = "no-wizard-overview__item";
185	      item.dataset.wizardNavItem = "";
186	
187	      const button = document.createElement("button");
188	      button.type = "button";
189	      button.className = "no-wizard-overview__button";
190	      button.dataset.wizardJump = String(index);
191	
192	      const corner = this._createOverviewCorner();
193	
194	      const head = document.createElement("span");
195	      head.className = "no-wizard-overview__head";
196	
197	      const rect = this._createOverviewRect();
198	
199	      const indexNode = document.createElement("span");
200	      indexNode.className = "no-wizard-overview__index f-body-3 --regular";
201	      indexNode.textContent = this._resolveNavLabel(index);
202	
203	      const body = document.createElement("span");
204	      body.className = "no-wizard-overview__body";
205	
206	      const value = document.createElement("span");
207	      value.className = "no-wizard-overview__value f-body-3 --regular";
208	      value.dataset.wizardStepValue = String(index);
209	
210	      head.append(rect, indexNode);
211	      body.append(value);
212	      button.append(corner, head, body);
213	      item.append(button);
214	      fragment.append(item);
215	    });
216	
217	    this._overviewList.replaceChildren(fragment);
218	    this._navItems = Array.from(
219	      this._root.querySelectorAll<HTMLElement>("[data-wizard-nav-item]"),
220	    );
221	    this._stepValues = Array.from(
222	      this._root.querySelectorAll<HTMLElement>("[data-wizard-step-value]"),
223	    );
224	  }
225	
226	  private _onClick(event: Event): void {
227	    if (this._submitting) return;
228	    const target = event.target;
229	    if (!(target instanceof HTMLElement)) return;
230	
231	    const jumpButton = target.closest<HTMLElement>("[data-wizard-jump]");
232	    if (jumpButton) {
233	      event.preventDefault();
234	      const nextIndex = Number(jumpButton.dataset.wizardJump);
235	      if (Number.isNaN(nextIndex) || nextIndex > this._resolveFurthestAccessibleStep()) return;
236	      this._jump(nextIndex);
237	      return;
238	    }
239	
240	    if (target.closest("[data-wizard-next]")) {
241	      event.preventDefault();
242	      this._next();
243	      return;
244	    }
245	
246	    if (target.closest("[data-wizard-prev]")) {
247	      event.preventDefault();
248	      this._prev();
249	    }
250	  }
251	
252	  private _onSubmit(event: Event): void {
253	    if (this._submitting) {
254	      event.preventDefault();
255	      event.stopPropagation();
256	      return;
257	    }
258	    if (!this._isSubmitAllowed()) {
259	      event.preventDefault();
260	      event.stopPropagation();
261	      return;
262	    }
263	
264	    const currentStep = this._steps[this._current];
265	    if (!currentStep) return;
266	    if (!this._triggerValidationAndCheck(currentStep)) {
267	      event.preventDefault();
268	      event.stopPropagation();
269	      return;
270	    }
271	
272	    event.preventDefault();
273	    event.stopPropagation();
274	    void this._submit();
275	  }
276	
277	  private _onFormKeydown(event: KeyboardEvent): void {
278	    if (this._submitting) {
279	      event.preventDefault();
280	      return;
281	    }
282	    if (event.key !== "Enter") return;
283	    if (this._isSubmitAllowed()) return;
284	
285	    const target = event.target;
286	    if (target instanceof HTMLTextAreaElement) return;
287	    if (target instanceof HTMLButtonElement) return;
288	
289	    event.preventDefault();
290	  }
291	
292	  private _next(): void {
293	    if (this._busy || this._submitting || this._current >= this._steps.length - 1) return;
294	    const currentStep = this._steps[this._current];
295	    if (!currentStep) return;
296	    if (!this._triggerValidationAndCheck(currentStep)) return;
297	    this._go(this._current + 1, "next");
298	  }
299	
300	  private _prev(): void {
301	    if (this._busy || this._submitting || this._current <= 0) return;
302	    this._go(this._current - 1, "prev");
303	  }
304	
305	  private _jump(nextIndex: number): void {
306	    if (this._busy || this._submitting) return;
307	    if (nextIndex < 0 || nextIndex >= this._steps.length) return;
308	    if (nextIndex === this._current) return;
309	    this._go(nextIndex, nextIndex > this._current ? "next" : "prev");
310	  }
311	
312	  private _go(nextIndex: number, direction: string): void {
313	    const currentStep = this._steps[this._current];
314	    const nextStep = this._steps[nextIndex];
315	    if (!currentStep || !nextStep) return;
316	
317	    this._busy = true;
318	
319	    requestAnimationFrame(() => {
320	      currentStep.classList.remove("is-active");
321	      currentStep.classList.toggle("is-prev", direction === "next");
322	
323	      requestAnimationFrame(() => {
324	        nextStep.classList.remove("is-prev");
325	        nextStep.classList.add("is-active");
326	        nextStep.scrollTop = 0;
327	
328	        this._current = nextIndex;
329	        this._syncIndicator();
330	        this._syncSidebar();
331	
332	        this._trackedTimeout(() => {
333	          currentStep.classList.remove("is-prev");
334	          this._busy = false;
335	        }, CONTACT_WIZARD.transitionMs + CONTACT_WIZARD.transitionBufferMs);
336	      });
337	    });
338	  }
339	
340	  private _syncIndicator(immediate = false): void {
341	    const currentElement =
342	      this._root.querySelector<HTMLElement>("[data-wizard-current]");
343	    const barElement = this._root.querySelector<HTMLElement>("[data-wizard-bar]");
344	
345	    if (currentElement) {
346	      currentElement.textContent = String(this._current + 1).padStart(2, "0");
347	    }
348	
349	    if (barElement) {
350	      const scale = (this._current + 1) / this._steps.length;
351	      barElement.style.transform = `scaleX(${scale})`;
352	    }
353	
354	    this._syncActionState(immediate);
355	    this._syncSubmitAvailability();
356	  }
357	
358	  private _syncActionState(immediate = false): void {
359	    const isFirstStep = this._current === 0;
360	    const isLastStep = this._current === this._steps.length - 1;
361	
362	    this._prevButtons.forEach((button) => {
363	      this._syncPreviousAction(button, isFirstStep, immediate);
364	    });
365	
366	    this._primaryActionButtons.forEach((button) => {
367	      this._syncPrimaryAction(button, isLastStep);
368	    });
369	  }
370	
371	  private _syncPreviousAction(
372	    button: HTMLButtonElement,
373	    isFirstStep: boolean,
374	    immediate = false,
375	  ): void {
376	    const target = this._resolvePreviousActionTarget(button);
377	    this._clearPreviousActionHideTimer(target);
378	
379	    if (isFirstStep) {
380	      button.disabled = true;
381	      button.setAttribute("aria-disabled", "true");
382	      target.setAttribute("aria-hidden", "true");
383	      target.toggleAttribute("inert", true);
384	
385	      if (
386	        immediate ||
387	        target.hidden ||
388	        target.classList.contains(INIT_DOM_CLASSES.boxHidden)
389	      ) {
390	        this._hidePreviousActionImmediately(target);
391	        return;
392	      }
393	
394	      this._hidePreviousActionWithTransition(target);
395	      return;
396	    }
397	
398	    this._showPreviousActionTarget(target, immediate);
399	    button.disabled = this._submitting;
400	    button.setAttribute(
401	      "aria-disabled",
402	      this._submitting ? "true" : "false",
403	    );
404	  }
405	
406	  private _syncPrimaryAction(
407	    button: HTMLButtonElement,
408	    isSubmitMode: boolean,
409	  ): void {
410	    button.type = isSubmitMode ? "submit" : "button";
411	    button.disabled = this._submitting;
412	    button.classList.toggle("no-wizard-action--next", !isSubmitMode);
413	    button.classList.toggle("no-wizard-action--submit", isSubmitMode);
414	    button.setAttribute("aria-hidden", "false");
415	    button.setAttribute("aria-disabled", this._submitting ? "true" : "false");
416	
417	    if (isSubmitMode) {
418	      button.removeAttribute("data-wizard-next");
419	    } else {
420	      button.dataset.wizardNext = "";
421	    }
422	
423	    const text = button.querySelector<HTMLElement>(".no-corner-btn__text");
424	    if (text) {
425	      const nextLabel = isSubmitMode ? "Submit" : "Next";
426	      if (text.textContent !== nextLabel) {
427	        text.textContent = nextLabel;
428	      }
429	    }
430	  }
431	
432	  private _syncSidebar(): void {
433	    this._syncStepSummaries();
434	    this._syncNavigationState();
435	  }
436	
437	  private _syncNavigationState(): void {
438	    const furthestAccessibleStep = this._resolveFurthestAccessibleStep();
439	
440	    this._navItems.forEach((item, index) => {
441	      const isCurrent = index === this._current;
442	      const isComplete = this._isStepSatisfied(this._steps[index]);
443	      const button = item.querySelector<HTMLButtonElement>(
444	        ".no-wizard-overview__button",
445	      );
446	
447	      item.classList.toggle("is-current", isCurrent);
448	      item.classList.toggle("is-complete", isComplete);
449	      item.classList.toggle("is-available", index <= furthestAccessibleStep);
450	
451	      if (!button) return;
452	      button.classList.toggle("is-framed", isCurrent);
453	      button.disabled = this._submitting || index > furthestAccessibleStep;
454	      button.setAttribute(
455	        "aria-label",
456	        `${this._resolveNavLabel(index)} ${this._resolveStepLabel(index)}`,
457	      );
458	      if (isCurrent) {
459	        button.setAttribute("aria-current", "step");
460	        return;
461	      }
462	      button.removeAttribute("aria-current");
463	    });
464	
465	    this._syncOverviewScroll();
466	  }
467	
468	  private _syncOverviewScroll(): void {
469	    if (!this._overviewList) return;
470	    if (this._lastOverviewScrollIndex === this._current) return;
471	
472	    const currentItem = this._navItems[this._current];
473	    if (!currentItem) return;
474	
475	    this._lastOverviewScrollIndex = this._current;
476	
477	    requestAnimationFrame(() => {
478	      const container = this._overviewList;
479	      if (!container) return;
480	
481	      const containerRect = container.getBoundingClientRect();
482	      const itemRect = currentItem.getBoundingClientRect();
483	      const padding = CONTACT_WIZARD.overviewScrollPadding;
484	      const offsetTop = itemRect.top - containerRect.top;
485	      const offsetBottom = itemRect.bottom - containerRect.bottom;
486	
487	      if (offsetTop < padding) {
488	        container.scrollTo({
489	          top: container.scrollTop + offsetTop - padding,
490	          behavior: "smooth",
491	        });
492	        return;
493	      }
494	
495	      if (offsetBottom > -padding) {
496	        container.scrollTo({
497	          top: container.scrollTop + offsetBottom + padding,
498	          behavior: "smooth",
499	        });
500	      }
501	    });
502	  }
503	
504	  private _syncStepSummaries(): void {
505	    this._stepValues.forEach((node) => {
506	      const stepIndex = Number(node.dataset.wizardStepValue);
507	      if (Number.isNaN(stepIndex)) return;
508	      this._renderStepValue(node, stepIndex);
509	    });
510	  }
511	
512	  private _renderStepValue(node: HTMLElement, stepIndex: number): void {
513	    if (stepIndex === 5) {
514	      this._renderDetailStepValue(node);
515	      return;
516	    }
517	
518	    const chipValues = this._resolveStepChipValues(stepIndex);
519	    const chipData = chipValues.map((value) => ({
520	      key: value,
521	      label: value,
522	    }));
523	    node.classList.toggle("is-chip-list", chipData.length > 0);
524	
525	    if (chipData.length > 0) {
526	      this._syncChipList(node, chipData);
527	      return;
528	    }
529	
530	    node.replaceChildren();
531	    node.textContent = "";
532	  }
533	
534	  private _renderDetailStepValue(node: HTMLElement): void {
535	    const detail = this._truncate(
536	      this._resolveInputValue("detail"),
537	      CONTACT_WIZARD.detailPreviewLength,
538	    );
539	    const attachment = this._resolveAttachmentName();
540	    const chipListSelector = ".no-wizard-overview__chip-list";
541	    const currentChipList = node.querySelector<HTMLElement>(chipListSelector);
542	    const chipData: ContactWizardChipData[] = [];
543	
544	    if (detail !== "") {
545	      chipData.push({
546	        key: "detail",
547	        label: detail,
548	      });
549	    }
550	
551	    if (attachment !== "") {
552	      chipData.push({
553	        key: "attachment",
554	        label: attachment,
555	        iconClass: this._resolveAttachmentIconClass(attachment),
556	      });
557	    }
558	
559	    node.classList.add("is-chip-list");
560	
561	    if (chipData.length === 0) {
562	      currentChipList?.remove();
563	      node.textContent = "";
564	      return;
565	    }
566	
567	    const chipList = currentChipList ?? document.createElement("span");
568	    chipList.className = "no-wizard-overview__chip-list is-chip-list";
569	    if (!chipList.parentElement) {
570	      node.append(chipList);
571	    }
572	    this._syncChipList(chipList, chipData);
573	  }
574	
575	  private _syncChipList(
576	    node: HTMLElement,
577	    chipValues: ContactWizardChipData[],
578	  ): void {
579	    const previousPositions = this._captureChipPositions(node);
580	    const chipSet = new Set(chipValues.map((chip) => chip.key));
581	    const existingChips = new Map(
582	      Array.from(
583	        node.querySelectorAll<HTMLElement>(".no-wizard-overview__chip:not(.is-ghost)"),
584	      ).map((chip) => [chip.dataset.wizardChipKey ?? "", chip]),
585	    );
586	    let layoutChanged = false;
587	
588	    chipValues.forEach((value, index) => {
589	      const existingChip = existingChips.get(value.key);
590	      const chip = existingChip ?? this._createChip(value, index);
591	      this._cancelChipLeave(chip);
592	      this._syncChipContent(chip, value);
593	      chip.style.animationDelay = `${index * CONTACT_WIZARD.chipStaggerMs}ms`;
594	
595	      if (!existingChip) {
596	        node.append(chip);
597	        layoutChanged = true;
598	      }
599	    });
600	
601	    existingChips.forEach((chip, value) => {
602	      if (chipSet.has(value)) return;
603	      this._detachChipWithGhost(node, chip);
604	      layoutChanged = true;
605	    });
606	
607	    if (!layoutChanged) return;
608	    this._animateChipReflow(node, previousPositions);
609	  }
610	
611	  private _createChip(value: ContactWizardChipData, index: number): HTMLElement {
612	    const chip = document.createElement("span");
613	    chip.className = "no-wizard-overview__chip is-entering";
614	    chip.dataset.wizardChipKey = value.key;
615	    chip.dataset.wizardChipValue = value.label;
616	    this._syncChipContent(chip, value);
617	    chip.style.animationDelay = `${index * CONTACT_WIZARD.chipStaggerMs}ms`;
618	    chip.addEventListener(
619	      "animationend",
620	      () => {
621	        chip.classList.remove("is-entering");
622	      },
623	      { once: true },
624	    );
625	    return chip;
626	  }
627	
628	  private _syncChipContent(
629	    chip: HTMLElement,
630	    value: ContactWizardChipData,
631	  ): void {
632	    chip.dataset.wizardChipKey = value.key;
633	    chip.dataset.wizardChipValue = value.label;
634	    chip.classList.toggle(
635	      "no-wizard-overview__chip--with-icon",
636	      value.iconClass !== undefined,
637	    );
638	
639	    const currentLabel = chip.querySelector<HTMLElement>(
640	      ".no-wizard-overview__chip-label",
641	    );
642	    const currentIcon = chip.querySelector<HTMLElement>(
643	      ".no-wizard-overview__chip-icon",
644	    );
645	
646	    if (value.iconClass !== undefined) {
647	      const icon = currentIcon ?? document.createElement("i");
