768	    node: HTMLElement,
769	    previousPositions: Map<HTMLElement, DOMRect>,
770	  ): void {
771	    requestAnimationFrame(() => {
772	      node
773	        .querySelectorAll<HTMLElement>(".no-wizard-overview__chip:not(.is-ghost)")
