788	            chip.animate(
789	              [
790	                { transform: `translate(${deltaX}px, ${deltaY}px)` },
791	                { transform: "translate(0, 0)" },
792	              ],
793	              {
794	                duration: CONTACT_WIZARD.chipMoveMs,
795	                easing: CONTACT_WIZARD.chipMoveEase,
796	                fill: "both",
797	              },
798	            ),
