1229	
1230	    const action = form.action.trim() === "" ? window.location.pathname : form.action;
1231	    const response = await fetch(action, {
1232	      method: (form.method || "POST").toUpperCase(),
1233	      body: new FormData(form),
1234	      headers: {
1235	        Accept: "application/json",
1236	        "X-Requested-With": "XMLHttpRequest",
1237	      },
1238	    });
1239	    const payload = await this._readSubmitResponse(response);
1240	    if (response.ok && payload.success) {
1241	      return payload;
1242	    }
1243	    throw new Error(payload.message);
