1429	  private _parseCssTimeList(value: string): number[] {
1430	    return value
1431	      .split(",")
1432	      .map((entry) => entry.trim())
1433	      .filter((entry) => entry !== "")
1434	      .map((entry) => {
1435	        if (entry.endsWith("ms")) {
1436	          return Number.parseFloat(entry);
1437	        }
1438	        if (entry.endsWith("s")) {
1439	          return Number.parseFloat(entry) * 1000;
1440	        }
1441	        return 0;
1442	      })
1443	      .filter((entry) => Number.isFinite(entry));
1444	  }
